style.css:
body {
    background-image: url("https://tenor.com/view/chaz-and-riley-cute-red-and-blue-purple-dance-gif-5489247584952788207") !important;
    background-repeat: no-repeat !important;
    background-position: center center !important;
    background-size: cover !important;
    background-attachment: fixed !important;
}

/* Optional dark overlay */
body::before {
    content: "";
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.3);
    pointer-events: none;
    z-index: -1;
}
